const { Browser } = require('happy-dom');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const fs = require('fs');
const path = require('path');

function TodoWorld() {
  this.browser = null;
  this.page = null;
}

function escapeJs(str) {
  return str
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r');
}

TodoWorld.prototype.loadApp = function () {
  const indexPath = path.resolve(__dirname, '../../index.html');
  const appJsPath = path.resolve(__dirname, '../../js/app.js');

  const html = fs.readFileSync(indexPath, 'utf8');
  const appJs = fs.readFileSync(appJsPath, 'utf8');

  // Extract body content from HTML
  const bodyMatch = html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
  const bodyContent = bodyMatch ? bodyMatch[1] : '';

  // Remove script tags from body content (we run them manually)
  const cleanedBody = bodyContent.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');

  // Set up HTML structure and run app.js
  this.page.evaluate(
    `document.documentElement.innerHTML = '<head></head><body>${escapeJs(cleanedBody)}</body>';`
  );
  this.page.waitUntilComplete();

  // Run app.js directly
  this.page.evaluate(appJs);
  this.page.waitUntilComplete();
};

TodoWorld.prototype.evaluate = function (script) {
  return this.page.evaluate(script);
};

TodoWorld.prototype.getText = function (selector) {
  return this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); return el ? el.textContent : null; })()`
  );
};

TodoWorld.prototype.getAttribute = function (selector, attr) {
  return this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); return el ? el.getAttribute('${attr}') : null; })()`
  );
};

TodoWorld.prototype.isVisible = function (selector) {
  return this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (!el) return false; const style = window.getComputedStyle(el); return style.display !== 'none' && style.visibility !== 'hidden'; })()`
  );
};

TodoWorld.prototype.hasClass = function (selector, cls) {
  return this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); return el ? el.classList.contains('${cls}') : false; })()`
  );
};

TodoWorld.prototype.clickElement = function (selector) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) el.click(); })()`
  );
};

TodoWorld.prototype.setInputValue = function (selector, value) {
  const escaped = escapeJs(value);
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) { el.value = '${escaped}'; el.dispatchEvent(new Event('input', { bubbles: true })); } })()`
  );
};

TodoWorld.prototype.pressEnter = function (selector) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) { el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true })); } })()`
  );
};

TodoWorld.prototype.pressEscape = function (selector) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) { el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Escape', keyCode: 27, bubbles: true })); } })()`
  );
};

TodoWorld.prototype.pressTab = function (selector) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) { el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', keyCode: 9, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Tab', keyCode: 9, bubbles: true })); } })()`
  );
};

TodoWorld.prototype.exists = function (selector) {
  return this.page.evaluate(
    `document.querySelector('${selector}') !== null`
  );
};

TodoWorld.prototype.querySelectorAllCount = function (selector) {
  return this.page.evaluate(
    `document.querySelectorAll('${selector}').length`
  );
};

TodoWorld.prototype.clearLocalStorage = function () {
  this.page.evaluate('localStorage.clear()');
};

TodoWorld.prototype.setLocalStorage = function (key, value) {
  const escaped = escapeJs(value);
  this.page.evaluate(`localStorage.setItem('${key}', '${escaped}')`);
};

TodoWorld.prototype.getLocalStorage = function (key) {
  return this.page.evaluate(`localStorage.getItem('${key}')`);
};

setWorldConstructor(TodoWorld);

Before(function () {
  this.browser = new Browser();
  this.page = this.browser.newPage();
});

After(function () {
  if (this.browser) {
    this.browser.close();
    this.browser = null;
    this.page = null;
  }
});

